class Solution {
public:
    vector<int> singleNumber(vector<int>& nums) {
        long long xor2 = 0;
        for (int x : nums) xor2 ^= x;
        long long mask = xor2 & -xor2;
        int a = 0, b = 0;
        for (int x : nums) {
            if (x & mask) a ^= x;
            else b ^= x;
        }
        return {a, b};
    }
};
